4. use vstd::prelude::*;
5. use vstd::atomic::*;
6. use vstd::invariant::*;
7. use vstd::resource::*;
8. use vstd::resource::ghost_var::*;
9. use vstd::iset::ISet;
10. 
11. verus! {
12. 
13. type ReadAU = AtomicUpdate<FlagToken, Commit<FlagToken>, ReadPred>;
14. type FlipAU = AtomicUpdate<FlagToken, Commit<FlagToken>, FlipPred>;
15. 
16. pub enum Protocol {
17.     Empty(GhostVarAuth<Option<FlipAU>>),
18.     Offering(Tracked<FlipAU>),
19.     Accepted,
20. }
21. 
22. use Protocol::*;
23. 
24. impl Protocol {
25.     proof fn take_empty(tracked self) -> (tracked out: GhostVarAuth<Option<FlipAU>>)
26.         requires self is Empty,
27.         ensures self == Empty(out),
28.     {
29.         match self {
30.             Empty(gva) => gva,
31.             _ => proof_from_false(),
32.         }
33.     }
34. 
35.     proof fn take_offer(tracked self) -> (tracked out: Tracked<FlipAU>)
36.         requires self is Offering,
37.         ensures self == Offering(out),
38.     {
39.         match self {
40.             Offering(au) => au,
41.             _ => proof_from_false(),
42.         }
43.     }
44. }
45. 
46. type K = (int, int, Loc, Loc);
47. type V = (PermissionBool, PermissionU32, GhostVarAuth<bool>, GhostVar<Option<FlipAU>>, Protocol);
48. 
49. pub struct FlagInv;
50. pub open spec const FLAG_INV: int = 2;
51. impl InvariantPredicate<K, V> for FlagInv {
52.     open spec fn inv(k: K, v: V) -> bool {
53.         let (value_id, pend_id, state_id, gv_id) = k;
54.         let (value_perm, pend_perm, state, gv, proto) = v;
55.         &&& value_perm.id() == value_id
56.         &&& pend_perm.id() == pend_id
57.         &&& state.id() == state_id
58.         &&& gv.id() == gv_id
59.         &&& state@ == value_perm.value()
60.         &&& pend_perm.value() < 3
61.         &&& match proto {
62.             Empty(gva) => {
63.                 &&& pend_perm.value() == 0
64.                 &&& gva.id() == gv_id
65.                 &&& gv@ is None
66.                 &&& gva@ is None
67.                 &&& gv@ == gva@
68.             }
69.             Offering(au) => {
70.                 &&& pend_perm.value() == 1
71.                 &&& gv@ is Some
72.                 &&& gv@->0 == au@
73.             },
74.             Accepted => {
75.                 &&& pend_perm.value() == 2
76.                 &&& gv@ is Some
77.                 &&& gv@->0.resolves()
78.             }
79.         }
80.     }
81. }
82. 
83. pub struct FlagToken {
84.     pub value: GhostVar<bool>,
85. }
86. 
87. impl FlagToken {
88.     pub open spec fn id(self) -> Loc {
89.         self.value.id()
90.     }
91. }
92. 
93. pub struct Flag {
94.     pub value: PAtomicBool,
95.     pub pending: PAtomicU32,
96.     pub inv: Tracked<AtomicInvariant<K, V, FlagInv>>,
97. }
98. 
99. impl Flag {
100.     pub open spec fn wf(self) -> bool {
101.         &&& self.inv@.constant().0 == self.value.id()
102.         &&& self.inv@.constant().1 == self.pending.id()
103.         &&& self.inv@.namespace() == FLAG_INV
104.     }
105. 
106.     pub open spec fn token_id(self) -> Loc {
107.         self.inv@.constant().2
108.     }
109. 
110.     pub fn new(init: bool) -> (out: (Self, Tracked<FlagToken>))
111.         ensures
112.             out.0.wf(),
113.             out.0.token_id() == out.1@.id(),
114.             out.1@.value@ == init,
115.     {
116.         let (value, Tracked(value_perm)) = PAtomicBool::new(init);
117.         let (pending, Tracked(pending_perm)) = PAtomicU32::new(0);
118.         let tracked (state_auth, state_var) = GhostVarAuth::new(init);
119.         let tracked (au_auth, au_var) = GhostVarAuth::new(None);
120.         let tracked inv = AtomicInvariant::new(
121.             (value.id(), pending.id(), state_auth.id(), au_auth.id()),
122.             (value_perm, pending_perm, state_auth, au_var, Empty(au_auth)),
123.             FLAG_INV,
124.         );
125. 
126.         let this = Self { value, pending, inv: Tracked(inv) };
127.         let tracked token = FlagToken { value: state_var };
128.         (this, Tracked(token))
129.     }
130. 
131.     pub fn read(&self) -> (out: bool)
132.         atomically (atomic_update) {
133.             type ReadPred,
134.             (old_token: FlagToken) -> (new_token: Commit<FlagToken>),
135.             requires
136.                 old_token.id() == self.token_id(),
137.             ensures
138.                 new_token@ == old_token,
139. 
140.             outer_mask ISet::<int>::full().remove(FLAG_INV),
141.             inner_mask none,
142.         },
143.         requires self.wf(),
144.         ensures out == old_token.value@,
145.     {
146.         let out;
147.         open_atomic_invariant!(self.inv.borrow() => v => {
148.             let tracked (mut value_perm, mut pend_perm, mut auth, mut gv, mut proto) = v;
149.             out = self.value.load(Tracked(&value_perm));
150. 
151.             proof {
152.                 try_open_atomic_update!(atomic_update, token=> {
153.                     auth.agree(&token.value);
154.                     assert(value_perm.value() == token.value@);
155.                     Tracked(Commit(token))
156.                 });
157. 
158.                 v = (value_perm, pend_perm, auth, gv, proto);
159.             }
160.         });
161. 
162.         return out;
163.     }
164. 
165.     pub fn flip(&self)
166.         atomically (atomic_update) {
167.             type FlipPred,
168.             (old_token: FlagToken) -> (new_token: Commit<FlagToken>),
169.             requires
170.                 old_token.id() == self.token_id(),
171.             ensures
172.                 new_token@.value@ == !old_token.value@,
173.                 new_token@.id() == old_token.id(),
174. 
175.             outer_mask any / [FLAG_INV],
176.             inner_mask none,
177.         },
178.         requires self.wf(),
179.     {
180.         let tracked mut au = atomic_update;
181. 
182.         loop invariant
183.             self.wf(),
184.             au == atomic_update,
185.         {
186.             match self.try_cancel_two_flips(Tracked(au)) {
187.                 Some(upd) => proof { au = upd.get() },
188.                 None => return,
189.             }
190. 
191.             match self.try_simple_flip(Tracked(au)) {
192.                 Some(upd) => proof { au = upd.get() },
193.                 None => return,
194.             }
195. 
196.             match self.try_handshake(Tracked(au)) {
197.                 Some(upd) => proof { au = upd.get() },
198.                 None => return,
199.             }
200.         }
201.     }
202. 
203.     fn try_cancel_two_flips(&self, Tracked(au): Tracked<FlipAU>) -> (out: Option<Tracked<FlipAU>>)
204.         requires
205.             self.wf(),
206.             au.pred().args(self),
207.         ensures
208.             match out {
209.                 Some(ret_au) => ret_au == au,
210.                 None => au.resolves(),
211.             }
212.     {
213.         let tracked mut maybe_au = Some(au);
214.         let res;
215. 
216.         open_atomic_invariant!(self.inv.borrow() => v => {
217.             let tracked (mut value_perm, mut pend_perm, mut auth, mut gv, mut proto) = v;
218.             res = self.pending.compare_exchange(Tracked(&mut pend_perm), 1, 2);
219. 
220.             proof {
221.                 v = (value_perm, pend_perm, auth, gv, proto);
222.             }
223.         });
224. 
225.         if res.is_ok() {
226.             return None;
227.         }
228. 
229.         Some(Tracked(maybe_au.tracked_take()))
230.     }
231. 
232.     fn try_simple_flip(&self, Tracked(au): Tracked<FlipAU>) -> (out: Option<Tracked<FlipAU>>)
233.         requires
234.             self.wf(),
235.             au.pred().args(self),
236.         ensures
237.             match out {
238.                 Some(ret_au) => ret_au == au,
239.                 None => au.resolves(),
240.             }
241.     {
242.         let tracked mut maybe_au = Some(au);
243.         let res;
244. 
245.         open_atomic_invariant!(self.inv.borrow() => v => {
246.             let tracked (mut value_perm, mut pend_perm, mut auth, mut gv, mut proto) = v;
247.             res = self.value.compare_exchange(Tracked(&mut value_perm), true, false);
248.             proof {
249.                 if res.is_ok() {
250.                     let tracked au = maybe_au.tracked_take();
251.                     try_open_atomic_update!(au, mut token => {
252.                         let ghost old_auth = auth@;
253.                         auth.update(&mut token.value, !old_auth);
254.                         Tracked(Commit(token))
255.                     });
256.                 }
257. 
258.                 v = (value_perm, pend_perm, auth, gv, proto);
259.             }
260.         });
261. 
262.         if res.is_ok() {
263.             return None;
264.         }
265. 
266.         let res;
267. 
268.         open_atomic_invariant!(self.inv.borrow() => v => {
269.             let tracked (mut value_perm, mut pend_perm, mut auth, mut gv, mut proto) = v;
270.             res = self.value.compare_exchange(Tracked(&mut value_perm), false, true);
271.             proof {
272.                 if res.is_ok() {
273.                     let tracked au = maybe_au.tracked_take();
274.                     try_open_atomic_update!(au, mut token => {
275.                         let ghost old_auth = auth@;
276.                         auth.update(&mut token.value, !old_auth);
277.                         Tracked(Commit(token))
278.                     });
279.                 }
280. 
281.                 v = (value_perm, pend_perm, auth, gv, proto);
282.             }
283.         });
284. 
285.         if res.is_ok() {
286.             return None;
287.         }
288. 
289.         Some(Tracked(maybe_au.tracked_take()))
290.     }
291. 
292.     fn try_handshake(&self, Tracked(au): Tracked<FlipAU>) -> (out: Option<Tracked<FlipAU>>)
293.         requires
294.             self.wf(),
295.             au.pred().args(self),
296.         ensures
297.             match out {
298.                 Some(ret_au) => ret_au == au,
299.                 None => au.resolves(),
300.             }
301.     {
302.         let tracked mut maybe_au = Some(au);
303.         let tracked mut auth_au = None;
304.         let res;
305. 
306.         open_atomic_invariant!(self.inv.borrow() => v => {
307.             let tracked (mut value_perm, mut pend_perm, mut auth, mut gv, mut proto) = v;
308.             res = self.pending.compare_exchange(Tracked(&mut pend_perm), 0, 1);
309. 
310.             proof {
311.                 if res.is_ok() {
312.                     let tracked au = maybe_au.tracked_take();
313.                     assert(proto is Empty);
314. 
315.                     let tracked mut gva = proto.take_empty();
316.                     assert(gva.id() == gv.id());
317.                     assert(gva@ is None);
318. 
319.                     gva.update(&mut gv, Some(au));
320.                     auth_au = Some(gva);
321. 
322.                     proto = Offering(Tracked(au));
323.                 }
324. 
325.                 v = (value_perm, pend_perm, auth, gv, proto);
326.             }
327.         });
328. 
329.         if res.is_err() {
330.             return Some(Tracked(maybe_au.tracked_take()));
331.         }
332. 
333.         assert(auth_au is Some);
334. 
335.         let res;
336. 
337.         open_atomic_invariant!(self.inv.borrow() => v => {
338.             let tracked (mut value_perm, mut pend_perm, mut auth, mut gv, mut proto) = v;
339.             res = self.pending.compare_exchange(Tracked(&mut pend_perm), 1, 0);
340. 
341.             proof {
342.                 if res.is_ok() {
343.                     assert(proto is Offering);
344.                     assert(maybe_au is None);
345.                     assert(auth_au is Some);
346. 
347.                     let tracked mut au = proto.take_offer();
348.                     let tracked mut gva = auth_au.tracked_take();
349.                     gva.agree(&gv);
350. 
351.                     gva.update(&mut gv, None);
352.                     assert(gva@ is None);
353. 
354.                     maybe_au = Some(au.get());
355.                     proto = Empty(gva);
356.                 } else {
357.                     assert(auth_au is Some);
358.                     let tracked mut gva = auth_au.tracked_borrow();
359.                     gva.agree(&gv);
360. 
361.                     assert(proto is Accepted);
362.                     assert(gva@ is Some);
363.                     let ghost au = gva@->0;
364.                     assert(au.resolves());
365.                 }
366. 
367.                 v = (value_perm, pend_perm, auth, gv, proto);
368.             }
369.         });
370. 
371.         if res.is_err() {
372.             open_atomic_invariant!(self.inv.borrow() => v => {
373.                 let tracked (mut value_perm, mut pend_perm, mut auth, mut gv, mut proto) = v;
374.                 self.pending.store(Tracked(&mut pend_perm), 0);
375. 
376.                 proof {
377.                     let tracked mut gva = auth_au.tracked_take();
378.                     gva.update(&mut gv, None);
379.                     proto = Empty(gva);
380.                     v = (value_perm, pend_perm, auth, gv, proto);
381.                 }
382.             });
383. 
384.             return None;
385.         }
386. 
387.         Some(Tracked(maybe_au.tracked_take()))
388.     }
389. }
