 ///
 ///         requires atomic_pre(px, ax),
 ///         ensures atomic_post(px, ax, ay),
 ///
 ///         outer_mask Eo,
 ///         inner_mask Ei,
 ///     },
 ///     requires private_pre(px),
 ///     ensures private_post(px, ax, ay, py),
