     pub proof fn get(tracked self) -> (tracked out: T)
         ensures
             self@ == out,
     {
         self.0
     }
 }

 impl<T> View for Commit<T> {
     type V = T;

     #[verifier::inline]
     open spec fn view(&self) -> T {
         self.0
     }
 }

 impl<T> UpdateTry for Commit<T> {
     open spec fn branch(self) -> UpdateControlFlow {
         UpdateControlFlow::Commit
     }
 }

 impl UpdateTry for () {
     open spec fn branch(self) -> UpdateControlFlow {
         UpdateControlFlow::Commit
     }
 }

